"""Informe sólo de corridas completas; nunca rellena resultados faltantes."""
from pathlib import Path
import argparse,json,html
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);a=p.parse_args();root=a.root
read=lambda p:json.loads(p.read_text())
for serie in ['C3','B6']:assert read(root/'resultados'/serie/'COMPLETE.json')['status']=='completed'
c=read(root/'resultados/C3/ensemble.json');b=read(root/'resultados/B6/comparacion.json');d=read(root/'resultados/C3/comparacion.json')
def convert(data,serie):
 base=data[0]['cuts']['11000']['ganancia'];out=[]
 for r in data:
  out.append({'serie':serie,'brazo':r['arm'],'variables':r['features'],'AUC':r.get('auc_ensemble',r.get('auc_validation')),'ganancia_10500':r['cuts']['10500']['ganancia'],'ganancia_11000':r['cuts']['11000']['ganancia'],'ganancia_11500':r['cuts']['11500']['ganancia'],'aciertos_11000':r['cuts']['11000']['aciertos'],'delta_control_11000':r['cuts']['11000']['ganancia']-base})
 return pd.DataFrame(out)
ct=convert(c,'C3_junio2021');bt=convert(b,'B6_octubre2019');pd.concat([ct,bt]).to_csv(root/'resumen_resultados.csv',index=False)
fig,axes=plt.subplots(1,2,figsize=(13,5),layout='constrained')
for ax,t,title in zip(axes,[ct,bt],['C3 · junio 2021 · ensemble de 20','B6 · octubre 2019 · una semilla']):
 vals=t.ganancia_11000/1e6;ax.bar(t.brazo,vals,color=['#607d8b','#21918c','#31688e']);ax.set_title(title);ax.set_ylabel('Ganancia a 11.000 (millones de pesos)');ax.tick_params(axis='x',labelrotation=15)
 for i,v in enumerate(vals):ax.text(i,v,f'{v:.2f}',ha='center',va='bottom')
 ax.set_ylim(min(0,vals.min()*1.1),max(vals)*1.15)
fig.savefig(root/'ganancias.png',dpi=150);plt.close(fig)
per=pd.read_csv(root/'resultados/C3/por_seed.csv');wide=per.pivot(index='seed',columns='arm',values='gain_11000')
fig,ax=plt.subplots(figsize=(10,4),layout='constrained')
for arm in ['C3_HOJA2500','C3_INTRAMES']:ax.plot(range(20),(wide[arm]-wide.C3_CONTROL)/1e6,'o-',label=arm)
ax.axhline(0,color='black',lw=1);ax.set_xticks(range(20),wide.index,rotation=60);ax.set_ylabel('Diferencia vs control (millones)');ax.set_xlabel('Semilla pareada');ax.legend();fig.savefig(root/'deltas_semillas.png',dpi=150);plt.close(fig)
def table(df):return df.to_html(index=False,float_format=lambda x:f'{x:,.6f}')
policy=pd.DataFrame([{'brazo':r['arm'],'contactos':r['policy_contacts'],'ganancia':r['policy_gain']} for r in b])
ratio_records=[]
for serie,arm in [('C3','C3_INTRAMES'),('B6','B6_FIJO'),('B6','B6_BO')]:
 paths=list((root/'resultados'/serie/arm).rglob('importance.csv'))
 for path in paths:
  im=pd.read_csv(path);total=im.gain.sum()
  for row in im[im.feature.str.startswith('intrames_')].itertuples():
   ratio_records.append({'brazo':arm,'ratio':row.feature,'gain_pct':100*row.gain/total,'usado':int(row.split>0)})
ratios=pd.DataFrame(ratio_records).groupby(['brazo','ratio']).agg(gain_pct_promedio=('gain_pct','mean'),modelos_que_lo_usan=('usado','sum')).reset_index()
ratios.to_csv(root/'importancia_ratios_nuevos.csv',index=False)
content='''<!doctype html><html lang="es"><meta charset="utf-8"><title>C3 y B6: ratios intrames</title><style>body{font:17px/1.55 system-ui;max-width:1200px;margin:35px auto;padding:20px;color:#193144}table{border-collapse:collapse;font-size:14px;width:100%}td,th{border:1px solid #ccd9df;padding:8px}th{background:#e9f1f4}img{width:100%}h2{margin-top:38px}.nota{padding:18px;background:#fff0d7}a{color:#176c8d}</style><h1>Experimento C3 y B6: ratios intrames</h1><p>Resultados reales de nuevas corridas en clari-c1-fundados. Dos series independientes: no comparar sus ganancias absolutas entre períodos.</p><div class="nota">Diseño exploratorio: junio 2021 y octubre 2019 ya se habían observado. No es una nueva prueba temporal independiente ni se realizó un envío a la competencia.</div><h2>Hipótesis</h2><p>Los cocientes de consumo, saldo, límites y operaciones de la misma foto pueden representar intensidad de uso mejor que las magnitudes por separado. Se separa este cambio de una regularización más fuerte en C3 y de la optimización de hiperparámetros en B6. No se replica el experimento ganador de ratios personales históricos.</p><h2>Diseño</h2><p>C3: control original, sólo hoja mínima2500 y sólo cuatro ratios nuevos; train marzo–abril2021, evaluación junio, BAJA+2,300 árboles,20 semillas pareadas. B6: control B5, B5+7ratios con sus mismos parámetros/281 árboles, y B6 reoptimizado con20 pruebas; train marzo–junio2019, validación agosto, target combinado y evaluación octubre. Métrica económica principal predefinida:11.000contactos. Bandas10.500/11.500 secundarias.</p><p>Las tres razones monto/operación agregadas a B6 ya existían en C3 y se excluyeron allí tras verificar igualdad. Las cuatro de tarjetas se calculan sobre suma Master+Visa, conservando marca observada y dejando NA si ambas faltan. Denominador positivo finito; numerador negativo finito conservado. No se agregaron los totales de tarjetas como nuevas predictoras, para no mezclar sus efectos con los de los cocientes.</p><h2>Resultados C3</h2>'''+table(ct)+'''<p>AUC de C3 corresponde al ensemble en junio; ganancia del ensemble no equivale al promedio de ganancias de las semillas.</p><h3>Diferencias pareadas por semilla</h3>'''+table(pd.DataFrame(d))+'''<img src="deltas_semillas.png" alt="Diferencias por semilla"><p>La dispersión describe aleatoriedad del entrenamiento en el mismo mes, no incertidumbre temporal entre meses.</p><h2>Resultados B6</h2>'''+table(bt)+'''<p>AUC de B6 corresponde a validación agosto2019; las ganancias a octubre2019. B6_FIJO vs B5 aísla el agregado de la familia manteniendo hiperparámetros y rondas; B6_BO agrega reoptimización. Una familia no identifica cuál ratio individual produjo el cambio.</p><img src="ganancias.png" alt="Ganancias de las dos series"><h3>Política elegida en validación: resultado secundario</h3>'''+table(policy)+'''<p>Cada modelo elige en agosto su máximo de ganancia, con desempate por menor número de contactos, y transfiere la fracción a octubre. No se elige un corte mirando octubre. Comparar estas cifras mezcla ranking y política; por eso11.000es el resultado principal.</p><h2>Limitaciones y siguientes experimentos</h2><ul><li>Períodos ya usados; ninguna afirmación de mejora futura independiente.</li><li>Para atribuir a un cociente, hacer ablaciones individuales posteriores con criterio fijado.</li><li>No se probó interacción de hoja2500 y ratios en C3: necesitaría cuarto brazo.</li><li>B6 tiene una semilla; no extrapolar su estabilidad desde las veinte semillas de C3.</li><li>El nuevo control C3 se entrena con el entorno de esta corrida; sus datos y código FE coinciden por hash con el original. Las versiones del entorno se registran para identificar diferencias de reproducción.</li></ul><h2>Entregable y reproducción</h2><p><a href="resumen_resultados.csv">Resumen CSV</a> · <a href="PROTOCOLO.txt">Protocolo previo</a> · <a href="REPRODUCIR.txt">Reproducir</a> · <a href="config/protocolo.json">Configuración</a></p><p>Código y métricas agregadas publicados; modelos, datos, matrices y scores individuales se conservan en respaldo privado. El control B5 debe reproducir exactamente su curva anterior antes de declarar completado el ensayo.</p></html>'''
content=content.replace('<h2>Limitaciones y siguientes experimentos</h2>','<h2>Uso de los ratios nuevos</h2>'+table(ratios)+'<p>Importancia interna normalizada por modelo; no es porcentaje de ganancia económica ni efecto causal. Si hay mejora, las ablaciones posteriores deben separar cada cociente.</p><h2>Limitaciones y siguientes experimentos</h2>')
support=pd.read_csv(root/'auditoria/soporte_marcas.csv').groupby(['serie','ratio'])[['ratio_observado','observado_con_soporte_marcas_distinto']].sum().reset_index()
support['porcentaje_soporte_distinto']=100*support.observado_con_soporte_marcas_distinto/support.ratio_observado
content=content.replace('<h2>Limitaciones y siguientes experimentos</h2>','<h2>Disponibilidad de datos por marca</h2>'+table(support)+'<p>En consumo/límite, una marca puede tener límite observado y consumo faltante. La suma ignora ese consumo faltante y conserva el límite observado; por eso este cociente puede representar disponibilidad y faltantes además de uso. No prueba que haya cero consumo real. Este diagnóstico no cambió la fórmula congelada ni seleccionó modelos. Una variante que exija soporte común sería otro experimento.</p><h2>Limitaciones y siguientes experimentos</h2>')
historic=pd.read_csv(root/'referencia_B0_B5.csv')
content=content.replace('<h2>Uso de los ratios nuevos</h2>','<h2>Referencia completa B0–B5 a igual presupuesto</h2>'+table(historic[historic.contactos.eq(11000)])+'<p>Resultados históricos del mismo octubre2019, presentados descriptivamente. Su inspección previa impide considerar esta extensión como una nueva evaluación independiente.</p><h2>Uso de los ratios nuevos</h2>')
content=content.replace('<h2>Hipótesis</h2>','<p><b>Ganar dinero no prueba que los ratios sean la causa:</b> los controles ya tienen ganancia positiva. El aporte de cada cambio se mide como diferencia contra su control, a igual presupuesto de contactos.</p><h2>Hipótesis</h2>')
changes=pd.read_csv(root/'cambios_seleccion.csv');composition=pd.read_csv(root/'composicion_11000.csv')
content=content.replace('<h2>Uso de los ratios nuevos</h2>','<h2>Qué cambió en los 11.000 seleccionados</h2>'+table(changes)+'<p>A igual número de contactos, cada acierto BAJA+2 neto adicional aporta exactamente1.100.000pesos de diferencia. La tabla muestra bajas detectadas que entran y bajas que se pierden al cambiar de ranking. Es una descomposición del resultado observado, no una atribución causal a un ratio particular.</p>'+table(composition)+'<p>En B6, BAJA+1 cuenta como positiva para AUC, pero no como acierto económico. Por eso el orden por AUC combinado puede diferir del orden por ganancia.</p><h2>Uso de los ratios nuevos</h2>')
conclusion = "C3: conservar el control como referencia. El ensemble con ratios pierde $6,6 millones y seis aciertos a 11.000 contactos; hoja mínima 2500 pierde $12,1 millones y once aciertos. Los ratios suben ligeramente el AUC, pero no la ganancia principal. Por semilla ganan 10 veces, empatan una y pierden nueve: no hay mejora uniforme. B6 fijo gana $5,5 millones y cinco aciertos frente a B5; reoptimizado gana $1,1 millones y un acierto. B6 fijo todavía queda debajo de los anteriores B2 ($222,2 millones) y B4 ($224,4 millones). No adoptar automáticamente ninguna variante: falta validar en otro período y repetir B6 con varias semillas."
content=content.replace('<h2>Hipótesis</h2>', '<h2>Conclusión de esta corrida</h2><p>'+conclusion+'</p><h2>Hipótesis</h2>')
content=content.replace('<h2>Entregable y reproducción</h2>', '<h2>Verificación final</h2><p>62 modelos verificados por hash; ganancias recalculadas desde todas las predicciones. C3 reprodujo sus 20 semillas y su ensemble de referencia en los tres cortes. B5 reprodujo exactamente su curva previa. <a href="verificacion_final.json">Detalle de controles</a>.</p><h2>Entregable y reproducción</h2>')
(root/'informe.html').write_text(content)
lines=['GUION PARA VIDEO GRUPAL — C3 Y B6 INTRAMES','',
'HIPÓTESIS. Probamos si cocientes de magnitudes de la misma foto agregan información útil sobre dos representaciones previas. No son los ratios personales históricos de otro experimento.',
'DISEÑO. En C3 comparamos control, sólo hoja mínima2500 y sólo cuatro ratios nuevos, con veinte semillas pareadas y300 árboles. En B6 comparamos B5, B5 más siete ratios con parámetros/rondas fijos, y la misma representación reoptimizada con veinte pruebas por AUC. El presupuesto principal se fijó en11.000 contactos.',
'RESULTADOS.']
for df in [ct,bt]:
 for row in df.itertuples():lines.append(f'{row.brazo}: ganancia {row.ganancia_11000:,}; {row.aciertos_11000} aciertos; diferencia contra su control {row.delta_control_11000:+,}.')
lines += [conclusion, 'LIMITACIONES. C3 se evalúa en junio2021 y B6 en octubre2019: sus ganancias absolutas no son comparables. Ambos períodos ya se habían observado. Las veinte semillas de C3 no son veinte meses independientes. B6 usa una sola semilla. La ganancia del ensemble no es la media de ganancias de las semillas.',
'CONCLUSIÓN. El efecto de agregar ratios se interpreta con el brazo de parámetros fijos; la diferencia entre fijo y BO muestra el resultado de reoptimizar. La importancia interna de un ratio no demuestra que genere ganancia. Estos resultados no prueban qué causó el éxito de un experimento anterior distinto.',
'SIGUIENTE PASO. Ablacionar los ratios individualmente si se justifica y validar fuera de los períodos ya utilizados. Revisar la interpretación de consumo sobre límite cuando las marcas tienen distintos campos observados. No adoptar una variante sólo por haber visto este test.']
(root/'guion_video.txt').write_text('\n\n'.join(lines))
print(pd.concat([ct,bt]).to_string(index=False))
